//! The simulator data structures shared with the simulator plugins, generated by bindgen from
//! `include/bono/{forecast,scoring,telemetry}.h` (see `build.rs`).
#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/sim.rs"));

use rusqlite::types::{ToSql, ToSqlOutput};
use std::{
    fmt::{self, Debug, Formatter},
    mem::{ManuallyDrop, MaybeUninit},
    ops::{Deref, DerefMut},
};

// The `bono_opt_*` types from bono.h, written by hand instead of generated (`build.rs`
// blocklists them) so `value` can be a `MaybeUninit`: it's only initialized when `present` is
// true, and C may leave anything in it otherwise (a garbage `bool`, a null string). Generated
// structs refer to them through the `_s` aliases, so their layout checks cover these types too.
macro_rules! copy_optional {
    ($name:ident, $alias:ident, $t:ty) => {
        #[repr(C)]
        #[derive(Clone, Copy)]
        pub struct $name {
            present: bool,
            value: MaybeUninit<$t>,
        }

        pub type $alias = $name;

        impl $name {
            #[inline]
            pub fn get(&self) -> Option<$t> {
                self.present.then(|| unsafe { self.value.assume_init() })
            }
        }

        impl From<Option<$t>> for $name {
            #[inline]
            fn from(value: Option<$t>) -> Self {
                match value {
                    Some(value) => Self {
                        present: true,
                        value: MaybeUninit::new(value),
                    },
                    None => Self::default(),
                }
            }
        }

        impl From<$name> for Option<$t> {
            #[inline]
            fn from(value: $name) -> Self {
                value.get()
            }
        }

        impl Default for $name {
            #[inline]
            fn default() -> Self {
                Self {
                    present: false,
                    value: MaybeUninit::uninit(),
                }
            }
        }

        impl Debug for $name {
            fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
                Debug::fmt(&self.get(), f)
            }
        }

        impl PartialEq for $name {
            #[inline]
            fn eq(&self, other: &Self) -> bool {
                self.get() == other.get()
            }
        }

        impl ToSql for $name {
            #[inline]
            fn to_sql(&self) -> rusqlite::Result<ToSqlOutput<'_>> {
                Ok(match self.get() {
                    Some(value) => value.into(),
                    None => rusqlite::types::Null.into(),
                })
            }
        }
    };
}

copy_optional!(bono_opt_f64, bono_opt_f64_s, f64);
copy_optional!(bono_opt_i64, bono_opt_i64_s, i64);
copy_optional!(bono_opt_boolean, bono_opt_boolean_s, bool);

#[repr(C)]
pub struct bono_opt_string {
    present: bool,
    value: MaybeUninit<bono_string_s>,
}

pub type bono_opt_string_s = bono_opt_string;

impl bono_opt_string {
    #[inline]
    pub fn as_deref(&self) -> Option<&str> {
        self.present
            .then(|| unsafe { self.value.assume_init_ref() }.deref())
    }
}

impl<T: Into<bono_string>> From<Option<T>> for bono_opt_string {
    #[inline]
    fn from(value: Option<T>) -> Self {
        match value {
            Some(value) => Self {
                present: true,
                value: MaybeUninit::new(value.into()),
            },
            None => Self::default(),
        }
    }
}

impl From<bono_opt_string> for Option<String> {
    #[inline]
    fn from(value: bono_opt_string) -> Self {
        // Moves `value` out without running this type's destructor
        let value = ManuallyDrop::new(value);
        value
            .present
            .then(|| unsafe { value.value.assume_init_read() }.into())
    }
}

impl Default for bono_opt_string {
    #[inline]
    fn default() -> Self {
        Self {
            present: false,
            value: MaybeUninit::uninit(),
        }
    }
}

impl Clone for bono_opt_string {
    fn clone(&self) -> Self {
        self.as_deref().map(str::to_owned).into()
    }
}

impl Debug for bono_opt_string {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        Debug::fmt(&self.as_deref(), f)
    }
}

impl PartialEq for bono_opt_string {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        self.as_deref() == other.as_deref()
    }
}

impl ToSql for bono_opt_string {
    #[inline]
    fn to_sql(&self) -> rusqlite::Result<ToSqlOutput<'_>> {
        Ok(match self.as_deref() {
            Some(value) => value.into(),
            None => rusqlite::types::Null.into(),
        })
    }
}

impl Drop for bono_opt_string {
    fn drop(&mut self) {
        if self.present {
            unsafe { self.value.assume_init_drop() };
        }
    }
}

// It owns its bytes like the `String` it's made from
unsafe impl Send for bono_string {}
unsafe impl Sync for bono_string {}

impl Default for bono_string {
    #[inline]
    fn default() -> Self {
        String::new().into()
    }
}

impl Deref for bono_string {
    type Target = str;

    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        unsafe { std::str::from_utf8_unchecked(std::slice::from_raw_parts(self.data, self.len)) }
    }
}

impl DerefMut for bono_string {
    #[inline(always)]
    fn deref_mut(&mut self) -> &mut Self::Target {
        unsafe {
            std::str::from_utf8_unchecked_mut(std::slice::from_raw_parts_mut(self.data, self.len))
        }
    }
}

impl Clone for bono_string {
    fn clone(&self) -> Self {
        self.deref().to_owned().into()
    }
}

impl From<String> for bono_string {
    #[inline]
    fn from(value: String) -> Self {
        let (data, len, cap) = value.into_raw_parts();
        Self { data, len, cap }
    }
}

impl From<Box<str>> for bono_string {
    #[inline]
    fn from(value: Box<str>) -> Self {
        value.into_string().into()
    }
}

impl From<bono_string> for String {
    #[inline]
    fn from(value: bono_string) -> Self {
        let value = ManuallyDrop::new(value);
        unsafe { String::from_raw_parts(value.data, value.len, value.cap) }
    }
}

impl From<bono_string> for Box<str> {
    #[inline]
    fn from(value: bono_string) -> Self {
        String::from(value).into_boxed_str()
    }
}

impl Drop for bono_string {
    #[inline]
    fn drop(&mut self) {
        drop(unsafe { String::from_raw_parts(self.data, self.len, self.cap) })
    }
}

/// Creates a string for C or C++ from the `len` bytes at `data`, replacing invalid UTF-8, since the
/// strings are only ever freed here. Declared in bono.h.
///
/// # Safety
/// `out` must be valid for writes, and `data` valid for reads of `len` bytes (or `len` zero).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bono_string_new(out: *mut bono_string, data: *const u8, len: usize) {
    let bytes = match len {
        0 => &[][..],
        _ => unsafe { std::slice::from_raw_parts(data, len) },
    };
    let string = String::from_utf8_lossy(bytes).into_owned();
    unsafe { out.write(string.into()) };
}

/// Frees a string made by `bono_string_new`. Declared in bono.h.
///
/// # Safety
/// `string` must point to a string made by `bono_string_new`, which isn't used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bono_string_drop(string: *mut bono_string) {
    unsafe { std::ptr::drop_in_place(string) }
}
